#include<bits/stdc++.h>
using namespace std;struct P{int x,y;};struct Geo{string word;vector<P>in,out,ctx;};
#include "fast_control_geometry.hpp"
using K=uint64_t;K key(P p){return K(uint32_t(p.x))<<32|uint32_t(p.y);}P rot(P p,int h){switch((h%4+4)%4){case 0:return p;case 1:return{p.y,-p.x};case 2:return{-p.x,-p.y};default:return{-p.y,p.x};}}
P pos;int heading,target,S,F,I=28,qfloor;int A[4]={0,22,20,10};int T[10][4]={{4,22,16,10},{16,2,16,18},{0},{0},{8,26,12,6},{20,6,12,14},{28,18,-8,14},{8,30,12,2},{20,10,12,10},{28,22,-8,10}};int keep[8]={0,1,4,5,6,7,8,9};unordered_map<K,char>color;vector<pair<K,char>>undo;vector<int>path,bestpath;mt19937_64 rng(871033);uint64_t attempts=0,legal=0,goals=0,rootnodes=0,cap;int maxdepth=0;bool found=false;P initial;int initialh;
int ht(P p){return p.y-p.x;} // phase1 rotation(y,-x), sum=y-x.
bool trace(string const&w){P ds[]={{0,1},{1,0},{0,-1},{-1,0}};for(char c:w){K k=key(pos);auto it=color.find(k);char old=it==color.end()?0:it->second;if(old==c||(!old&&ht(pos)>F&&c=='L'))return false;undo.push_back({k,old});color[k]=c;heading=(heading+(c=='R'?1:3))%4;pos.x+=ds[heading].x;pos.y+=ds[heading].y;}return true;}
void restore(size_t n){while(undo.size()>n){auto[k,c]=undo.back();undo.pop_back();if(c)color[k]=c;else color.erase(k);}}
void emit(){cout<<"COUNTERCONTROL {\"target\":"<<target<<",\"I\":"<<I<<",\"initial_pose\":["<<initial.x<<","<<initial.y<<","<<initialh<<"],\"goal_pose\":["<<pos.x<<","<<pos.y<<","<<heading<<"],\"packet_ids\":[";for(int i=0;i<path.size();i++)cout<<(i?",":"")<<path[i];cout<<"]}\n";}
void dfs(int depth){if(found||attempts>=cap||rootnodes++>=3000||depth>=128)return;if(depth>maxdepth){maxdepth=depth;bestpath=path;}array<pair<double,int>,8>order;for(int i=0;i<8;i++)order[i]={double(rng()%100)-30.0*(2*ht(pos)+T[keep[i]][(heading+1)%4]),keep[i]};sort(order.begin(),order.end());for(auto[prio,a]:order){if(found||attempts>=cap||rootnodes>=3000)return;attempts++;int q=ht(pos);bool goal=a==target&&heading==0&&q==0;if(goal)goals++;if(2*q+A[(heading+1)%4]>=S||(!goal&&2*q+T[a][(heading+1)%4]>=S))continue;size_t n=undo.size();P p=pos;int h=heading;if(!trace(geometry[a].word)){restore(n);pos=p;heading=h;continue;}size_t nm=undo.size();P pe=pos;int he=heading;bool ok=trace("LLLLRLRRRRL");restore(nm);pos=pe;heading=he;if(!ok){restore(n);pos=p;heading=h;continue;}legal++;path.push_back(a);if(goal){found=true;pos=p;heading=h;emit();return;}if(ht(pos)>=qfloor)dfs(depth+1);path.pop_back();restore(n);pos=p;heading=h;}}
int main(int ac,char**av){target=ac>1?atoi(av[1]):7;cap=ac>2?stoull(av[2]):10000000;I=ac>3?atoi(av[3]):28;S=T[target][1];F=(S-I-1>=0?(S-I-1)/2:-((I+1-S+1)/2));auto start=chrono::steady_clock::now();int roots=0;while(attempts<cap&&!found){roots++;color.clear();undo.clear();path.clear();rootnodes=0;initialh=rng()%4;int q=F-int(rng()%6);q-=(q-initialh+1000)%2;initial={0,q};pos=initial;heading=initialh;qfloor=q-12;for(P z:vector<P>{{-1,-1},{-1,0},{0,-1},{0,0},{1,0}}){P r=rot(z,heading);color[key({pos.x+r.x,pos.y+r.y})]='R';}if(2*q+A[(heading+1)%4]<S)dfs(0);}
cout<<"SUMMARY {\"target\":"<<target<<",\"I\":"<<I<<",\"F\":"<<F<<",\"attempts\":"<<attempts<<",\"legal_packets\":"<<legal<<",\"goal_pose_tests\":"<<goals<<",\"max_prefix_packets\":"<<maxdepth<<",\"roots\":"<<roots<<",\"found\":"<<(found?"true":"false")<<",\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}\n";}
